package com.mynikatech.memgine.component.support

import org.jdbi.v3.sqlobject.config.RegisterBeanMapper
import org.jdbi.v3.sqlobject.customizer.Bind
import org.jdbi.v3.sqlobject.statement.SqlQuery

@RegisterBeanMapper(SupportRequestDto::class)
interface SupportSql {
    @SqlQuery("SELECT * FROM support_customer_create(:id,:organizationId,:customerUserId,:category,:issueType,:subject,:description,:destination)") fun create(@Bind("id") id:String,@Bind("organizationId") organizationId:String?,@Bind("customerUserId") customerUserId:String,@Bind("category") category:String,@Bind("issueType") issueType:String,@Bind("subject") subject:String,@Bind("description") description:String,@Bind("destination") destination:String): SupportRequestCreatedDto
    @SqlQuery("SELECT * FROM support_customer_list(:userId,:limit,:offset)") fun customerList(@Bind("userId") userId:String,@Bind("limit") limit:Int,@Bind("offset") offset:Int):List<SupportRequestDto>
    @SqlQuery("SELECT * FROM support_org_list(:organizationId,:actorId,:category,:status,:priority,:limit,:offset)") fun orgList(@Bind("organizationId") organizationId:String,@Bind("actorId") actorId:String,@Bind("category") category:String?,@Bind("status") status:String?,@Bind("priority") priority:String?,@Bind("limit") limit:Int,@Bind("offset") offset:Int):List<SupportRequestDto>
    @SqlQuery("SELECT * FROM support_platform_list(:actorId,:organizationId,:category,:status,:priority,:destination,:limit,:offset)") fun platformList(@Bind("actorId") actorId:String,@Bind("organizationId") organizationId:String?,@Bind("category") category:String?,@Bind("status") status:String?,@Bind("priority") priority:String?,@Bind("destination") destination:String?,@Bind("limit") limit:Int,@Bind("offset") offset:Int):List<SupportRequestDto>
    @SqlQuery("SELECT * FROM support_customer_detail(:id,:actorId)") fun customerDetail(@Bind("id") id:String,@Bind("actorId") actorId:String):SupportRequestDto?
    @SqlQuery("SELECT * FROM support_org_detail(:id,:organizationId,:actorId)") fun orgDetail(@Bind("id") id:String,@Bind("organizationId") organizationId:String,@Bind("actorId") actorId:String):SupportRequestDto?
    @SqlQuery("SELECT * FROM support_platform_detail(:id,:actorId)") fun platformDetail(@Bind("id") id:String,@Bind("actorId") actorId:String):SupportRequestDto?
    @SqlQuery("SELECT * FROM support_messages(:id,:actorId,:viewer)") @RegisterBeanMapper(SupportMessageDto::class) fun messages(@Bind("id") id:String,@Bind("actorId") actorId:String,@Bind("viewer") viewer:String):List<SupportMessageDto>
    @SqlQuery("SELECT * FROM support_events(:id,:actorId,:viewer)") @RegisterBeanMapper(SupportEventDto::class) fun events(@Bind("id") id:String,@Bind("actorId") actorId:String,@Bind("viewer") viewer:String):List<SupportEventDto>
    @SqlQuery("SELECT support_add_message(:messageId,:id,:actorId,:role,:type,:body,:internal)") fun addMessage(@Bind("messageId") messageId:String,@Bind("id") id:String,@Bind("actorId") actorId:String,@Bind("role") role:String,@Bind("type") type:String,@Bind("body") body:String,@Bind("internal") internal:Boolean):Boolean
    @SqlQuery("SELECT support_customer_reopen(:id,:actorId,:reason)") fun reopen(@Bind("id") id:String,@Bind("actorId") actorId:String,@Bind("reason") reason:String):Boolean
    @SqlQuery("SELECT support_customer_close(:id,:actorId)") fun close(@Bind("id") id:String,@Bind("actorId") actorId:String):Boolean
    @SqlQuery("SELECT support_customer_submit_feedback(:id,:actorId,:rating,:comment)") fun submitFeedback(@Bind("id") id:String,@Bind("actorId") actorId:String,@Bind("rating") rating:String?,@Bind("comment") comment:String?):Boolean
    @SqlQuery("SELECT * FROM support_feedback(:id,:actorId,:viewer)") @RegisterBeanMapper(SupportFeedbackDto::class) fun feedback(@Bind("id") id:String,@Bind("actorId") actorId:String,@Bind("viewer") viewer:String):SupportFeedbackDto?
    @SqlQuery("SELECT support_admin_update(:id,:organizationId,:actorId,:status,:priority,:assignedTo,:resolution,:version)") fun update(@Bind("id") id:String,@Bind("organizationId") organizationId:String,@Bind("actorId") actorId:String,@Bind("status") status:String?,@Bind("priority") priority:String?,@Bind("assignedTo") assignedTo:String?,@Bind("resolution") resolution:String?,@Bind("version") version:Int):Boolean
    @SqlQuery("SELECT support_platform_update(:id,:actorId,:status,:priority,:resolution,:version)") fun platformUpdate(@Bind("id") id:String,@Bind("actorId") actorId:String,@Bind("status") status:String?,@Bind("priority") priority:String?,@Bind("resolution") resolution:String?,@Bind("version") version:Int):Boolean
    @SqlQuery("SELECT * FROM support_payment_investigation_detail(:id,:organizationId,:actorId)") @RegisterBeanMapper(PaymentInvestigationDto::class) fun paymentInvestigation(@Bind("id") id:String,@Bind("organizationId") organizationId:String,@Bind("actorId") actorId:String):PaymentInvestigationDto?
    @SqlQuery("SELECT * FROM support_payment_exception_candidates(:id,:organizationId,:actorId)") @RegisterBeanMapper(PaymentExceptionCandidateDto::class) fun paymentExceptionCandidates(@Bind("id") id:String,@Bind("organizationId") organizationId:String,@Bind("actorId") actorId:String):List<PaymentExceptionCandidateDto>
    @SqlQuery("SELECT support_escalate_payment_investigation(:id,:organizationId,:actorId,:reason,:reference,:description)") fun escalatePaymentInvestigation(@Bind("id") id:String,@Bind("organizationId") organizationId:String,@Bind("actorId") actorId:String,@Bind("reason") reason:String,@Bind("reference") reference:String?,@Bind("description") description:String?):String
    @SqlQuery("SELECT support_link_payment_exception(:id,:organizationId,:actorId,:exceptionId)") fun linkPaymentException(@Bind("id") id:String,@Bind("organizationId") organizationId:String,@Bind("actorId") actorId:String,@Bind("exceptionId") exceptionId:String):String
    @SqlQuery("SELECT support_payment_investigation_transition(:id,:organizationId,:actorId,:state,:reason)") fun transitionPaymentInvestigation(@Bind("id") id:String,@Bind("organizationId") organizationId:String,@Bind("actorId") actorId:String,@Bind("state") state:String,@Bind("reason") reason:String):Boolean
    @SqlQuery("SELECT * FROM counter_support_list(:organizationId,:storeId,:staffId,:actorId,:limit,:offset)") fun counterList(@Bind("organizationId") organizationId:String,@Bind("storeId") storeId:String,@Bind("staffId") staffId:String,@Bind("actorId") actorId:String,@Bind("limit") limit:Int,@Bind("offset") offset:Int):List<SupportRequestDto>
    @SqlQuery("SELECT * FROM counter_support_detail(:id,:organizationId,:storeId,:staffId,:actorId)") fun counterDetail(@Bind("id") id:String,@Bind("organizationId") organizationId:String,@Bind("storeId") storeId:String,@Bind("staffId") staffId:String,@Bind("actorId") actorId:String):SupportRequestDto?
    @SqlQuery("SELECT * FROM counter_support_messages(:id,:organizationId,:storeId,:staffId,:actorId)") @RegisterBeanMapper(SupportMessageDto::class) fun counterMessages(@Bind("id") id:String,@Bind("organizationId") organizationId:String,@Bind("storeId") storeId:String,@Bind("staffId") staffId:String,@Bind("actorId") actorId:String):List<SupportMessageDto>
    @SqlQuery("SELECT * FROM counter_support_events(:id,:organizationId,:storeId,:staffId,:actorId)") @RegisterBeanMapper(SupportEventDto::class) fun counterEvents(@Bind("id") id:String,@Bind("organizationId") organizationId:String,@Bind("storeId") storeId:String,@Bind("staffId") staffId:String,@Bind("actorId") actorId:String):List<SupportEventDto>
    @SqlQuery("SELECT counter_support_add_message(:messageId,:id,:organizationId,:storeId,:staffId,:actorId,:body,:internal)") fun counterMessage(@Bind("messageId") messageId:String,@Bind("id") id:String,@Bind("organizationId") organizationId:String,@Bind("storeId") storeId:String,@Bind("staffId") staffId:String,@Bind("actorId") actorId:String,@Bind("body") body:String,@Bind("internal") internal:Boolean):Boolean
    @SqlQuery("SELECT counter_support_transition(:id,:organizationId,:storeId,:staffId,:actorId,:status,:resolution,:version)") fun counterTransition(@Bind("id") id:String,@Bind("organizationId") organizationId:String,@Bind("storeId") storeId:String,@Bind("staffId") staffId:String,@Bind("actorId") actorId:String,@Bind("status") status:String,@Bind("resolution") resolution:String?,@Bind("version") version:Int):Boolean
    @SqlQuery("SELECT * FROM counter_support_payment_investigation(:id,:organizationId,:storeId,:staffId,:actorId)") @RegisterBeanMapper(PaymentInvestigationDto::class) fun counterPaymentInvestigation(@Bind("id") id:String,@Bind("organizationId") organizationId:String,@Bind("storeId") storeId:String,@Bind("staffId") staffId:String,@Bind("actorId") actorId:String):PaymentInvestigationDto?
    @SqlQuery("SELECT * FROM counter_support_payment_exception_summary(:id,:organizationId,:storeId,:staffId,:actorId)") @RegisterBeanMapper(PaymentExceptionCandidateDto::class) fun counterPaymentExceptionSummary(@Bind("id") id:String,@Bind("organizationId") organizationId:String,@Bind("storeId") storeId:String,@Bind("staffId") staffId:String,@Bind("actorId") actorId:String):List<PaymentExceptionCandidateDto>
}
